GMG - Roll on Tables.command:
(async () => {
  let options = '';
  game.tables.contents.forEach((t) => {
    if (
      t.folder &&
      (t.folder.name === 'Symbaroum GMG - Tables' ||
        t.folder.name === 'Symbaroum - Guia do Mestre - Tabelas' ||
        t.folder.name === '01.06 Under, Above & Beyond' ||
        t.folder.name === '01.06 Sob, Acima e Além' ||
        t.folder.name === '01.07 Goal Orientated Roleplaying' ||
        t.folder.name === '01.07 Interpretação Orientada a Objetivos' ||
        t.folder.name === '02.01 Advanced Traps' ||
        t.folder.name === '02.01 Armadilhas Avançadas' ||
        t.folder.name === '02.02 Pitched Battle' ||
        t.folder.name === '02.02 Batalha Campal' ||
        t.folder.name === '02.03 Managing a Domain' ||
        t.folder.name === '02.03 Gerenciando um Domínio' ||
        t.folder.name === '02.09 Events' ||
        t.folder.name === '02.09 Eventos' ||
        t.folder.name === '02.10 The Treasures of the Ruins' ||
        t.folder.name === '02.10 O Tesouro das Ruínas' ||
        t.folder.name === '02.11 Exploring Ruins' ||
        t.folder.name === '02.11 Explorando Ruínas' ||
        t.folder.name === '02.12 Ceremonies' ||
        t.folder.name === '02.12 Cerimônias' ||
        t.folder.name === 'Monster Codex' ||
        t.folder.name === 'Códice de Monstros') &&
      t.folder.name != null
    ) {
      options = options.concat(`<option value="${t.id}">${t.folder.name} - ${t.name}</option>`);
    }
  });
  let template = `
                      <form>
                          <div class="form-group">
                              <label>Selecionar tabela</label>
                              <select id="tableSelect">${options}</select>
                          </div>
                          <div class="form-group">
                              <label>Rolagens na tabela?</label>
                              <input type="text" id="inputNbr" value=1>
                          </div>
                          <div class="form-group">
                              <label>Modificador?</label>
                              <input type="text" id="inputMod" value="0">
                          </div>
                      </form>`;

  let buttons = {};
  if (game.tables.size > 0) {
    buttons = {
      draw: {
        icon: '<i class="fas fa-check"></i>',
        label: `Rolar`,
        callback: async (html) => {
          const tableId = html.find('#tableSelect')[0].value;
          const table = game.tables.get(tableId);
          const drawNumber = parseInt(html.find('#inputNbr')[0].value || '0', 10);
          const formula = table.formula;
          const modifier = parseInt(html.find('#inputMod')[0].value || '0', 10);

          for (let i = 0; i < drawNumber; i++) {
            const roll = await new Roll(formula + ' + ' + modifier).evaluate();
            await table.draw({ roll: roll });
          }
        },
      },
      cancel: {
        icon: '<i class="fas fa-times"></i>',
        label: `Cancelar`,
      },
    };
  } else {
    template = `<div style="text-align: center">Não há tabelas disponíveis para rolagem!</div><br>`;
    buttons = {
      draw: {
        icon: '<i class="fas fa-check"></i>',
        label: 'OK',
      },
    };
  }

  new Dialog(
    {
      title: `Rolar na tabela selecionada`,
      content: template,
      buttons: buttons,
      default: 'draw',
    },
    {
      width: 530,
    }
  ).render(true);
})();
